function e3dc_eeg_tariff_archive_meta() {
    return [
        'source' => 'Bundesnetzagentur EEG-Fördersätze Archiv',
        'valid_from' => '2018-01-01',
        'valid_to' => '2026-07-31',
        'url' => 'https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/ErneuerbareEnergien/EEG_Foerderung/Archiv_VergSaetze/start.html',
    ];
}

function e3dc_eeg_tariff_archive_find($commissioningDate) {
    $date = trim((string)$commissioningDate);
    if ($date === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) return null;
    foreach (e3dc_eeg_tariff_archive_rows() as $row) {
        if (!is_array($row) || count($row) < 3) continue;
        if ($date >= (string)$row[0] && $date <= (string)$row[1]) return $row;
    }
    return null;
}

function e3dc_eeg_tariff_current_row() {
    return e3dc_eeg_tariff_archive_find('2026-02-01');
}

function e3dc_eeg_tariff_extract_tiers($row, $basis, $systemType, $feedType) {
    if (!is_array($row) || count($row) < 3 || !is_array($row[2])) return [];
    $basis = in_array($basis, ['feed_in_tariff', 'market_premium'], true) ? $basis : 'feed_in_tariff';
    $systemType = in_array($systemType, ['building', 'other'], true) ? $systemType : 'building';
    $feedType = in_array($feedType, ['partial', 'full'], true) ? $feedType : 'partial';
    $basisRows = $row[2][$basis] ?? null;
    if (!is_array($basisRows)) return [];
    $systemRows = $basisRows[$systemType] ?? ($basisRows['building'] ?? null);
    if (!is_array($systemRows)) return [];
    $tiers = $systemRows[$feedType] ?? ($systemRows['partial'] ?? []);
    return is_array($tiers) ? $tiers : [];
}

function e3dc_eeg_tariff_tiers_for_config($config) {
    $rateSource = trim((string)($config['direct_marketing_eeg_rate_source'] ?? 'manual'));
    if ($rateSource === 'manual' || $rateSource === '') return [];
    $commissioning = trim((string)($config['direct_marketing_eeg_commissioning_date'] ?? ''));
    $row = ($rateSource === 'bnetza_current_2026_02')
        ? e3dc_eeg_tariff_current_row()
        : e3dc_eeg_tariff_archive_find($commissioning);
    $tiers = e3dc_eeg_tariff_extract_tiers(
        $row,
        trim((string)($config['direct_marketing_eeg_compensation_basis'] ?? 'feed_in_tariff')),
        trim((string)($config['direct_marketing_eeg_system_type'] ?? 'building')),
        trim((string)($config['direct_marketing_eeg_feed_type'] ?? 'partial'))
    );
    $normalized = [];
    foreach ($tiers as $tier) {
        if (!is_array($tier) || count($tier) < 2) continue;
        $normalized[] = ['limit_kwp' => (float)$tier[0], 'rate_ct' => (float)$tier[1]];
    }
    return $normalized;
}

function e3dc_eeg_tariff_source_warning($commissioningDate, $rateSource) {
    $meta = e3dc_eeg_tariff_archive_meta();
    $date = trim((string)$commissioningDate);
    $rateSource = trim((string)$rateSource);
    if ($rateSource === 'manual' || $rateSource === '') return '';
    if ($rateSource === 'bnetza_current_2026_02') {
        if ($date !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date) && ($date < '2026-02-01' || $date > '2026-07-31')) {
            return 'Die fest gewählte aktuelle BNetzA-Tabelle gilt nur für Inbetriebnahmen vom 2026-02-01 bis 2026-07-31.';
        }
        return '';
    }
    if ($date === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
        return 'Für die automatische BNetzA-Archivwahl muss ein Inbetriebnahmedatum hinterlegt sein.';
    }
    if ($date < $meta['valid_from'] || $date > $meta['valid_to']) {
        return 'Das eingebettete BNetzA-Archiv deckt aktuell nur Inbetriebnahmen vom ' . $meta['valid_from'] . ' bis ' . $meta['valid_to'] . ' ab; bitte Manuell / Sondertarif verwenden.';
    }
    return '';
}
